PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" varchar not null, "queue" varchar not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "personal_access_tokens" ("id" integer primary key autoincrement not null, "tokenable_type" varchar not null, "tokenable_id" integer not null, "name" text not null, "token" varchar not null, "abilities" text, "last_used_at" datetime, "expires_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "wa_accounts" ("id" integer primary key autoincrement not null, "name" varchar not null, "phone" varchar, "session_id" varchar not null, "status" varchar not null default 'DISCONNECTED', "created_at" datetime, "updated_at" datetime, "disconnect_email_enabled" tinyint(1) not null default '1', "disconnect_email_interval" integer not null default '10', "last_disconnect_email_sent_at" datetime, "category" varchar, "approval_status" varchar not null default 'APPROVED', "supervisor_id" integer);
CREATE TABLE IF NOT EXISTS "lead_messages" ("id" integer primary key autoincrement not null, "lead_id" integer not null, "sender" varchar, "message" text not null, "is_from_me" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("lead_id") references "leads"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "role" varchar not null default 'ADMIN', "status" varchar not null default 'PENDING', "wa_account_id" integer, "phone" varchar, foreign key("wa_account_id") references "wa_accounts"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "pipeline_stages" ("id" integer primary key autoincrement not null, "wa_account_id" integer, "name" varchar not null, "order" integer not null default '1', "color" varchar not null default 'purple', "created_at" datetime, "updated_at" datetime, "is_default" tinyint(1) not null default '0', foreign key("wa_account_id") references "wa_accounts"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "stage_triggers" ("id" integer primary key autoincrement not null, "wa_account_id" integer, "pipeline_stage_id" integer not null, "keyword" varchar not null, "created_at" datetime, "updated_at" datetime, foreign key("wa_account_id") references "wa_accounts"("id") on delete cascade, foreign key("pipeline_stage_id") references "pipeline_stages"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "smtp_settings" ("id" integer primary key autoincrement not null, "mail_mailer" varchar not null default 'smtp', "mail_host" varchar, "mail_port" integer not null default '587', "mail_username" varchar, "mail_password" varchar, "mail_encryption" varchar default 'tls', "mail_from_address" varchar not null default 'no-reply@difitech.id', "mail_from_name" varchar not null default 'Difitech CRM Alert', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "leads" ("id" integer primary key autoincrement not null, "name" varchar not null, "phone" varchar not null, "stage" varchar not null default ('Inquiries'), "created_at" datetime, "updated_at" datetime, "notes" text, "priority" integer not null default ('0'), "wa_account_id" integer, "assigned_user_id" integer, foreign key("wa_account_id") references wa_accounts("id") on delete set null on update no action, foreign key("assigned_user_id") references "users"("id") on delete set null);
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE INDEX "failed_jobs_connection_queue_failed_at_index" on "failed_jobs" ("connection", "queue", "failed_at");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE INDEX "personal_access_tokens_tokenable_type_tokenable_id_index" on "personal_access_tokens" ("tokenable_type", "tokenable_id");
CREATE UNIQUE INDEX "personal_access_tokens_token_unique" on "personal_access_tokens" ("token");
CREATE INDEX "personal_access_tokens_expires_at_index" on "personal_access_tokens" ("expires_at");
CREATE UNIQUE INDEX "wa_accounts_session_id_unique" on "wa_accounts" ("session_id");
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE UNIQUE INDEX "leads_phone_unique" on "leads" ("phone");
COMMIT;
